    #[test]
    fn alpha_programs_and_notes_follow_the_input() {
        let draw = |id: u64, alpha: Option<protocol::geometry::PreviewParameter>| {
            let mut draw = test_draw(id);
            draw.alpha = alpha;
            draw.material_id = None;
            draw
        };
        let partial = |lit: &LitScene| {
            lit.notes
                .iter()
                .filter(|n| n.reason.starts_with("alpha between 0 and 1"))
                .map(|n| n.draws)
                .sum::<usize>()
        };
        let mut manifest = scene_of(vec![]);
        manifest.draws = vec![
            draw(0, None),
            draw(1, Some(parameter("alpha", "float", &[1.], &[]))),
            draw(2, Some(parameter("alpha", "float", &[0.], &[]))),
            draw(3, Some(parameter("alpha", "float", &[0.5], &[]))),
            draw(6, Some(parameter("alpha", "float", &[0.25], &[]))),
            draw(4, Some(parameter("alpha", "texture", &[], &["r"]))),
            draw(5, Some(parameter("alpha", "texture", &[], &["r"]))),
        ];
        let lit = evaluate(&manifest, &BTreeMap::new());
        let programs: Vec<_> = manifest
            .draws
            .iter()
            .zip(&lit.alpha_of)
            .map(|(_, program)| *program)
            .collect();
        assert_eq!(programs[..2], [0, 0], "no alpha and alpha 1 stay opaque");
        assert_ne!(programs[2], 0, "alpha 0 always discards");
        assert_eq!(programs[3], 0, "a literal at 0.5 draws opaque");
        assert_ne!(programs[4], 0, "a literal below it discards");
        assert_ne!(programs[5], 0);
        assert_eq!(programs[5], programs[6], "one texture, one program");
        assert_eq!(partial(&lit), 4, "{:?}", lit.notes);

        manifest.draws[2].area_light = Some(protocol::geometry::AreaLightRecord {
            implementation: "diffuse".into(),
            source: None,
            parameters: vec![],
        });
        let lit = evaluate(&manifest, &BTreeMap::new());
        assert!(
            lit.notes
                .iter()
                .any(|n| n.reason.starts_with("emitter with alpha") && n.draws == 1)
        );
    }

