    #[test]
    fn mapping_rows_stay_exact_far_from_the_world_origin() {
        let mut texture = float_texture("r", "float");
        texture.implementation = "fbm".into();
        texture.world_from_texture[3] = 1e7;
        let mut manifest = scene_of(vec![named_material(
            "a",
            "diffuse",
            vec![parameter("reflectance", "texture", &[], &["c"])],
        )]);
        manifest.textures[1] = texture.clone();
        manifest.textures[1].name = "c".into();
        manifest.textures[1].value_type = "spectrum".into();
        let lit = evaluate(&manifest, &BTreeMap::new());
        // Texture x = world x - 1e7; a position 0.25 from an origin at 1e7 + 0.5
        // lands on 0.75, which f32 world coordinates could not represent.
        let rows = lit.mapping_rows([1e7 + 0.5, 0., 0.]);
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0][0] * 0.25 + rows[0][3], 0.75);
    }

    /// An image replaced by its average reads no coordinates, so its map must
    /// not stay behind for the next texture to pick up.
    #[test]
    fn over_budget_images_leave_no_mapping_behind() {
        let mut image = float_texture("i", "spectrum");
        image.implementation = "imagemap".into();
        image.parameters = vec![
            parameter("filename", "string", &[], &["i.png"]),
            parameter("mapping", "string", &[], &["planar"]),
        ];
        let mut parent = float_texture("p", "spectrum");
        parent.parameters = vec![parameter("tex1", "texture", &[], &["i"])];
        let mut manifest = scene_of(vec![named_material(
            "a",
            "diffuse",
            vec![parameter("reflectance", "texture", &[], &["p"])],
        )]);
        manifest.textures.extend([image, parent]);
        let ops = |capacity| {
            evaluate_with_image_capacity(&manifest, &BTreeMap::new(), capacity)
                .texture_instructions
                .iter()
                .map(|i| i.op)
                .collect::<Vec<_>>()
        };
        use texture_vm::{OP_CHECKERBOARD, OP_IMAGE, OP_MAP, OP_SPECTRUM};
        assert_eq!(ops(1), [OP_MAP, OP_IMAGE, OP_SPECTRUM, OP_CHECKERBOARD]);
        assert_eq!(ops(0), [OP_SPECTRUM, OP_SPECTRUM, OP_CHECKERBOARD]);
    }

    /// A child a literal amount never selects cannot make the mix transparent.
    #[test]
    fn mix_transmission_skips_children_with_zero_weight() {
        let transmission = |amount: f64| {
            let lit = evaluate(
                &scene_of(vec![
                    named_material(
                        "outer",
                        "mix",
                        vec![
                            parameter("materials", "string", &[], &["inner", "opaque"]),
                            parameter("amount", "float", &[0.], &[]),
                        ],
                    ),
                    named_material(
                        "inner",
                        "mix",
                        vec![
                            parameter("materials", "string", &[], &["opaque", "glass"]),
                            parameter("amount", "float", &[amount], &[]),
                        ],
                    ),
                    named_material("opaque", "diffuse", vec![]),
                    named_material("glass", "dielectric", vec![]),
                ]),
                &BTreeMap::new(),
            );
            (
                lit.appearances[0].transmission,
                lit.appearances[3].transmission,
            )
        };
        assert_eq!(transmission(0.).0, 0.);
        let (partial, glass) = transmission(0.5);
        assert_eq!(partial, glass);
        assert_eq!(transmission(1.).0, glass);
    }

    #[test]
    fn unshadeable_mixes_turn_gray_with_a_note() {
        let mix = |name: &str, a: &str, b: &str| {
            named_material(
                name,
                "mix",
                vec![parameter("materials", "string", &[], &[a, b])],
            )
        };
        let cycle = evaluate(
            &scene_of(vec![mix("x", "y", "y"), mix("y", "x", "x")]),
            &BTreeMap::new(),
        );
        let missing = evaluate(&scene_of(vec![mix("x", "nope", "nope")]), &BTreeMap::new());
        // Four levels of doubling give 16 leaves, over MAX_MIX_LEAVES.
        let too_many = evaluate(
            &scene_of(vec![
                mix("l1", "l2", "l2"),
                mix("l2", "l3", "l3"),
                mix("l3", "l4", "l4"),
                mix("l4", "leaf", "leaf"),
                named_material("leaf", "diffuse", vec![]),
            ]),
            &BTreeMap::new(),
        );
        for lit in [cycle, missing, too_many] {
            assert_eq!(lit.appearances[0].kind, KIND_LAMBERT);
            assert_eq!(lit.appearances[0].diffuse, [0.5; 3]);
            assert!(
                lit.notes.iter().any(|n| n.reason.starts_with("mix:")),
                "{:?}",
                lit.notes
            );
        }
    }

