    fn png_pixel(rgb: [u8; 3]) -> Vec<u8> {
        let image = image::RgbImage::from_pixel(3, 1, image::Rgb(rgb));
        let mut bytes = std::io::Cursor::new(Vec::new());
        image::DynamicImage::ImageRgb8(image)
            .write_to(&mut bytes, image::ImageFormat::Png)
            .unwrap();
        bytes.into_inner()
    }

    #[test]
    fn image_encoding_is_decoded_and_invalid_encodings_are_rejected() {
        let bytes = png_pixel([128, 128, 128]);
        let linear = decode_texture(&test_texture("linear"), &bytes).unwrap();
        let srgb = decode_texture(&test_texture("sRGB"), &bytes).unwrap();
        assert!((linear.get_pixel(1, 0)[0] - 128. / 255.).abs() < 1e-5);
        assert!((srgb.get_pixel(1, 0)[0] - 0.21586).abs() < 1e-4);
        assert!(decode_texture(&test_texture("mystery"), &bytes).is_err());
        assert!(normalize_encoding("gamma 0").is_err());
    }

    /// Absent image bytes are this read's shape, not the content's
    /// failure — they must never be memoised as one, or a later read the
    /// desktop skipped on the memo's word would keep folding forever.
    #[test]
    fn absent_control_map_bytes_fail_without_memoising() {
        let manifest = GeometryManifest {
            blobs: BTreeMap::from([(
                "light/0".to_owned(),
                protocol::package::PackageFile {
                    size: 16,
                    sha256: "abc".into(),
                },
            )]),
            ..Default::default()
        };
        let mut memos = ImageMemos::default();
        let error = memos
            .control_map("light/0", &manifest, &BTreeMap::new(), "goniometric", None)
            .unwrap_err();
        assert!(error.to_string().contains("was not found"), "{error}");
        assert!(
            memos.control_maps.is_empty(),
            "an absent read is not a decode failure of the content"
        );
        // The same identity with its bytes decodes and memoises.
        let blobs = BTreeMap::from([("light/0".to_string(), png_pixel([10, 20, 30]))]);
        assert!(
            memos
                .control_map("light/0", &manifest, &blobs, "goniometric", None)
                .is_ok()
        );
        assert_eq!(memos.control_maps.len(), 1);
        // A real decode failure (bytes present, content invalid) still
        // memoises.
        let mut strict = ImageMemos::default();
        assert!(
            strict
                .control_map(
                    "light/0",
                    &manifest,
                    &BTreeMap::from([("light/0".to_string(), b"not a png".to_vec())]),
                    "goniometric",
                    None
                )
                .is_err()
        );
        assert_eq!(strict.control_maps.len(), 1);
    }

    #[test]
    fn absent_texture_bytes_average_to_the_fallback_without_memoising() {
        let manifest = GeometryManifest {
            textures: vec![float_texture("r", "spectrum")],
            blobs: BTreeMap::from([(
                "texture/spectrum/r".to_owned(),
                protocol::package::PackageFile {
                    size: 16,
                    sha256: "abc".into(),
                },
            )]),
            ..Default::default()
        };
        let mut memos = ImageMemos::default();
        assert_eq!(
            memos.average_of(
                "texture/spectrum/r",
                &manifest,
                &manifest.textures,
                &BTreeMap::new()
            ),
            [0.5f32; 3]
        );
        assert!(
            memos.averages.is_empty(),
            "the fallback colour of an absent read is not memoised"
        );
        // With bytes the true average memoises.
        let blobs = BTreeMap::from([("texture/spectrum/r".to_string(), png_pixel([100, 50, 25]))]);
        let real = memos.average_of("texture/spectrum/r", &manifest, &manifest.textures, &blobs);
        assert_ne!(real, [0.5f32; 3]);
        assert_eq!(memos.averages.len(), 1);
    }

    #[test]
    fn an_uploaded_texture_answers_its_average_without_bytes() {
        // PR #339 review: a resident image demoted on a later update has no
        // bytes in that read; its upload must have memoised the average.
        let manifest = GeometryManifest {
            textures: vec![float_texture("r", "spectrum")],
            blobs: BTreeMap::from([(
                "texture/spectrum/r".to_owned(),
                protocol::package::PackageFile {
                    size: 16,
                    sha256: "abc".into(),
                },
            )]),
            ..Default::default()
        };
        let key = "texture/spectrum/r";
        let blobs = BTreeMap::from([(key.to_string(), png_pixel([100, 50, 25]))]);
        let expected = average_texture(key, &manifest.textures, &blobs);
        let identity = image_identity(key, &manifest, &manifest.textures).unwrap();
        let decoded = decode_texture(&manifest.textures[0], &blobs[key]).unwrap();
        let mut memos = ImageMemos::default();
        memos.note_average(&identity, &decoded);
        assert_eq!(
            memos.average_of(key, &manifest, &manifest.textures, &BTreeMap::new()),
            expected
        );
    }

    #[test]
    fn radiance_hdr_textures_decode_as_linear_light_above_one() {
        // image 0.24's DynamicImage path would give min(v, 1)^(1/2.2) here.
        let mut bytes = Vec::new();
        image::codecs::hdr::HdrEncoder::new(&mut bytes)
            .encode(&[image::Rgb([4.0f32, 0.25, 1.0]); 3], 3, 1)
            .unwrap();
        let mut record = test_texture("linear");
        record.parameters.clear();
        let decoded = decode_texture(&record, &bytes).unwrap();
        let [r, g, b, _] = decoded.get_pixel(1, 0).0;
        assert!((r - 4.0).abs() < 0.05, "light above 1.0 survives: {r}");
        assert!(
            (g - 0.25).abs() < 0.01,
            "HDR is linear, not gamma-encoded: {g}"
        );
        assert!((b - 1.0).abs() < 0.02, "{b}");
    }

    #[test]
    fn gamma_parameter_matches_pbrt_string_and_legacy_bool_forms() {
        let bytes = png_pixel([128, 128, 128]);
        let mut record = test_texture("linear");
        record.parameters = vec![protocol::geometry::PreviewParameter {
            name: "gamma".into(),
            value_type: "float".into(),
            floats: vec![2.2],
            texts: vec![],
            truncated: false,
        }];
        let decoded = decode_texture(&record, &bytes).unwrap();
        assert!((decoded.get_pixel(0, 0)[0] - (128. / 255.0f32).powf(2.2)).abs() < 1e-5);
        record.parameters[0].floats[0] = 1.0;
        let decoded = decode_texture(&record, &bytes).unwrap();
        assert!((decoded.get_pixel(0, 0)[0] - 0.21586).abs() < 1e-4);
        record.parameters[0].floats[0] = 0.0;
        let decoded = decode_texture(&record, &bytes).unwrap();
        assert!((decoded.get_pixel(0, 0)[0] - 128. / 255.).abs() < 1e-5);
    }

