    #[test]
    fn texture_array_capacity_obeys_layer_and_memory_limits() {
        let bytes_per_layer = (TEXTURE_SIZE as u64)
            .pow(2)
            .saturating_mul(8)
            .saturating_mul(4)
            / 3;
        let memory_layers = (TEXTURE_MEMORY_BUDGET / bytes_per_layer) as usize;
        assert!(memory_layers > 8);
        // The shared texture budget is 256 MiB: the array
        // path fits 24 of its fixed 1024² RGBA16Float layers now, still
        // under MAX_TEXTURES.
        assert_eq!(memory_layers, 24);
        assert_eq!(MAX_TEXTURES, 64);
    }

