    /// Parse a PBRT source and evaluate its lit scene, as the renderer does.
    fn evaluated(source: &str) -> (GeometryManifest, LitScene) {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("emitter.pbrt");
        std::fs::write(&path, source).unwrap();
        let parsed = scene_parse::parse_scene(path, scene_parse::ParseOptions::default()).unwrap();
        let lit = evaluate(&parsed.manifest, &parsed.blobs);
        (parsed.manifest, lit)
    }

    /// The calibration framing of em1.pbrt: an emitter quad at z = 3 facing a
    /// camera at the origin.
    fn emitter_scene(lights: &[&str]) -> String {
        let blocks = lights
            .iter()
            .map(|light| {
                format!(
                    "AttributeBegin\nAreaLightSource \"diffuse\" {light}\nShape \"trianglemesh\" \"point3 P\" [-1 -1 3 1 -1 3 1 1 3 -1 1 3] \"integer indices\" [0 2 1 0 3 2]\nAttributeEnd\n"
                )
            })
            .collect::<String>();
        format!("WorldBegin\n{blocks}")
    }

    /// The diffuse radiance the palette gave the nth emitter draw: its
    /// appearance must be a KIND_EMISSIVE lobe at all.
    fn emitter_surface(manifest: &GeometryManifest, lit: &LitScene, ordinal: usize) -> [f32; 3] {
        let draw = manifest
            .draws
            .iter()
            .enumerate()
            .filter(|(_, draw)| draw.area_light.is_some())
            .nth(ordinal)
            .map(|(index, _)| index)
            .expect("the scene holds an emitter draw");
        let slot = lit.appearance_of[draw] as usize;
        assert!(
            slot < lit.appearances.len(),
            "emitter draw {draw} shaded as its base material"
        );
        assert_eq!(
            lit.appearances[slot].kind, KIND_EMISSIVE,
            "emitter draw {draw} shaded as a regular material"
        );
        lit.appearances[slot].diffuse
    }

    /// A `scale 0.1` emitter's surface shows L × 0.1: r4 renders the board
    /// 0.099, while Lit saturated at 1 before the fix.
    #[test]
    fn scaled_emitter_surfaces_show_l_times_scale() {
        let (manifest, lit) =
            evaluated(&emitter_scene(&["\"rgb L\" [1 1 1] \"float scale\" [0.1]"]));
        assert_close(emitter_surface(&manifest, &lit, 0), [0.1; 3]);
    }

    /// A blackbody emitter's surface shows `blackbody_rgb` × scale: pre-fix
    /// Lit read the kelvin as radiance and saturated before the fix.
    #[test]
    fn blackbody_emitter_surfaces_show_blackbody_rgb_times_scale() {
        let (manifest, lit) = evaluated(&emitter_scene(&[
            "\"blackbody L\" [5500] \"float scale\" [0.1]",
        ]));
        assert_close(
            emitter_surface(&manifest, &lit, 0),
            blackbody_rgb(5500.).map(|v| v * 0.1),
        );
    }

    /// The palette key is the resolved radiance, so equal colours at
    /// different scales shade from their own slots, not one shared white.
    #[test]
    fn emitters_of_equal_colour_and_different_scale_shade_apart() {
        let (manifest, lit) = evaluated(&emitter_scene(&[
            "\"rgb L\" [1 1 1] \"float scale\" [0.1]",
            "\"rgb L\" [1 1 1] \"float scale\" [0.2]",
        ]));
        let dim = emitter_surface(&manifest, &lit, 0);
        let bright = emitter_surface(&manifest, &lit, 1);
        assert_ne!(dim, bright, "scale differences must not share a slot");
        assert_close(dim, [0.1; 3]);
        assert_close(bright, [0.2; 3]);
    }

    /// An emitter named with `power` shows the power-matched radiance its
    /// light emits, as r4's DiffuseAreaLight renders both from one Lemit
    /// using the same power-matched radiance as the light.
    #[test]
    fn powered_emitter_surfaces_match_their_emitted_radiance() {
        let (manifest, lit) = evaluated(&emitter_scene(&[
            "\"rgb L\" [1 1 1] \"float scale\" [0.2] \"float power\" [7]",
        ]));
        let surface = emitter_surface(&manifest, &lit, 0);
        let polygon = lit
            .lights
            .iter()
            .find(|light| light.kind[0] == LIGHT_POLYGON)
            .expect("the emitter emits a polygon light");
        assert_close(
            surface,
            [polygon.color[0], polygon.color[1], polygon.color[2]].map(f64::from),
        );
        // The power must actually have rescaled the radiance, as in r4:
        // 7 W over the 4 m² quad is 0.2 × 7/(π·4) ≈ 0.111, not L × scale.
        assert!(
            (polygon.color[0] as f64 - 0.2).abs() > 1e-3,
            "power left the radiance at L × scale"
        );
    }

    /// `rebind_with_frame` binds the frame its caller computed: `evaluate`
    /// already shaded the emitters for the palette, so the closing bind
    /// must not shade them a second time and drop the caller's frame
    /// (branch review).
    #[test]
    fn rebind_binds_the_frame_its_caller_computed() {
        let (manifest, mut lit) = evaluated(&emitter_scene(&[
            "\"rgb L\" [1 1 1] \"float scale\" [0.2] \"float power\" [7]",
        ]));
        let mut frame = frame_emitters(&manifest.draws, &lit.emitter_geometry, 0);
        assert_eq!(frame.lights.len(), 1);
        frame.lights[0].color = [0.75, 0.5, 0.25, 0.];
        rebind_with_frame(&manifest.draws, frame, &mut lit);
        let light = lit
            .lights
            .iter()
            .find(|light| light.kind[0] == LIGHT_POLYGON)
            .expect("the emitter still emits its polygon light");
        assert_eq!(
            [light.color[0], light.color[1], light.color[2]],
            [0.75, 0.5, 0.25],
            "the rebind re-shaded the emitters instead of using the given frame"
        );
    }

    /// A scale gizmo edit re-runs `rebind` with a changed matrix: a
    /// `power`-named emitter's radiance is area-matched, so it changes,
    /// and the surface must follow it to a new emissive slot — not fall
    /// back to its base material until the scene is reinstalled (branch
    /// review). Twice as large, the 4 m² quad's radiance falls by four.
    #[test]
    fn scaled_power_emitters_stay_emissive_across_rebinds() {
        let (mut manifest, mut lit) = evaluated(&emitter_scene(&[
            "\"rgb L\" [1 1 1] \"float scale\" [0.2] \"float power\" [7]",
        ]));
        manifest.draws[0].world_from_object = vec![[
            2., 0., 0., 0., 0., 2., 0., 0., 0., 0., 2., 0., 0., 0., 0., 1.,
        ]];
        rebind(&manifest.draws, &mut lit);
        rebind(&manifest.draws, &mut lit);
        let surface = emitter_surface(&manifest, &lit, 0);
        assert_close(surface, [0.2 * 7. / (PI * 16.); 3]);
        let polygon = lit
            .lights
            .iter()
            .find(|light| light.kind[0] == LIGHT_POLYGON)
            .expect("the scaled emitter still emits its polygon light");
        assert_close(
            surface,
            [polygon.color[0], polygon.color[1], polygon.color[2]].map(f64::from),
        );
    }

    /// Each scale step of a powered emitter resolves a new radiance; the
    /// slot of the one no draw uses any more is freed, so a long drag never
    /// exhausts the appearance budget and the surface keeps glowing.
    #[test]
    fn repeated_emitter_resizes_do_not_leak_appearance_slots() {
        let (mut manifest, mut lit) = evaluated(&emitter_scene(&[
            "\"rgb L\" [1 1 1] \"float scale\" [0.2] \"float power\" [7]",
        ]));
        let steps = MAX_APPEARANCES * 2;
        for step in 1..=steps {
            let s = 1. + step as f64 * 0.01;
            manifest.draws[0].world_from_object =
                vec![[s, 0., 0., 0., 0., s, 0., 0., 0., 0., s, 0., 0., 0., 0., 1.]];
            rebind(&manifest.draws, &mut lit);
        }
        assert_eq!(lit.appearances.len(), lit.emitter_base + 1);
        let surface = emitter_surface(&manifest, &lit, 0);
        let s = 1. + steps as f64 * 0.01;
        assert_close(surface, [0.2 * 7. / (PI * 4. * s * s); 3]);
    }

